// creates an augmented 3x3 matrix for affine transformation from matrix A and vector b
mat3 AugmentedMatrix(mat2 A, vec2 b){

    mat3 AA = mat3(A);
    vec3 bb = vec3(b,1.);
    // last column is b, 1.
    AA[2] = bb;

    return AA;

}

// inverse of a 2x2 matric
mat2 Inv(mat2 A){

    float a = A[0][0],
          b = A[1][0],
          c = A[0][1],
          d = A[1][1];

    return mat2(a/(a*d-b*c), -b/(a*d-b*c), -c/(a*d-b*c), d/(a*d-b*c));
}

// draw a circle of radius r with center at the origin with lorenzian width
float Circle(vec2 uv, float r, float width){

    return pow(width/2.,2.)/(pow(length(uv)-r,2.)+pow(width/2.,2.));

}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalize pixel coordinates 
    vec2 uv = fragCoord/iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x/iResolution.y;

    // global variables
    float PI = 3.14159265,
          w0 = .6,
        seed = 0.1,
        phi0 = 0.,
           t = iTime;

    // elements of matrix A are harmonic in time
    float a = 1.5*sin(0.9*w0*t + 1.0*PI + phi0),
          b = 3.0*sin(0.8*w0*t + 0.5*PI + phi0),
          c = 2.0*sin(0.7*w0*t + 0.0*PI + phi0),
          d = 2.5*sin(0.6*w0*t + 0.1*PI + phi0);

    mat2 A = mat2(a,c,b,d);

    // elements of translation vector are harmonic in time
    vec2 v = vec2(0.15*sin(0.7*w0*t + 1.0*PI + phi0),
                  0.12*sin(0.5*w0*t + 0.0*PI + phi0));

    // make augmented matrix 
    mat3 M = AugmentedMatrix(Inv(A), -Inv(A)*v); 

    float mask = 0.5*Circle(vec2(M*vec3(uv,1.)), 0.05, 0.01);

    // output to screen
    fragColor = vec4(vec3(mask),1.0);
}
